'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc,formText,type RoomType} from '@/lib/pilot';
import {useMemo} from 'react';
import {afterDays,type RateBook} from '@/lib/rates';
import {PaymentReadiness} from '@/components/payment-readiness';
import {integrationHealth} from '@/lib/integration-health';
type Connection={connection_id:string;ota_property_id:string;inventory_authority:string;room_types:Record<string,string>;enabled:boolean;has_secret:boolean};
type Review={event_id:string;booking_id:string;source_version:number;application_outcome:string;resolution_outcome:string|null;review_reason:string|null;is_current:boolean;can_reprocess:boolean};
async function readConnections(tenant:string,property:string){
 let timer:ReturnType<typeof setTimeout>|undefined;
 try{return await Promise.race([Promise.all([hotelRpc<Connection[]>('connections',{p_tenant:tenant,p_property:property}),hotelRpc<Review[]>('review_events',{p_tenant:tenant,p_property:property})]),new Promise<never>((_,reject)=>{timer=setTimeout(()=>reject(Error('Connection information timed out. Select Refresh to retry.')),30000)})])}finally{clearTimeout(timer)}
}
async function connectionCommand<T=unknown>(name:string,args:Record<string,unknown>):Promise<T>{
 let timer:ReturnType<typeof setTimeout>|undefined;
 try{return await Promise.race([hotelRpc<T>(name,args),new Promise<never>((_,reject)=>{timer=setTimeout(()=>reject(Error('The connection action could not be confirmed. It may still finish. Select Refresh and review the saved status before trying again.')),30000)})])}finally{clearTimeout(timer)}
}
type ConnectionsProps={actor:string;tenant:string;property:string;role:string;types:RoomType[];businessDate:string};
export function ConnectionsPanel(props:ConnectionsProps){return <ConnectionsWorkspace key={JSON.stringify([props.actor,props.tenant,props.property,props.role])} {...props}/>;}
function ConnectionsWorkspace({actor,tenant,property,role,types,businessDate}:ConnectionsProps){
 const [loaded,setLoaded]=useState(false);
 const [rows,setRows]=useState<Connection[]>([]),[reviews,setReviews]=useState<Review[]>([]),[edit,setEdit]=useState<Connection|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');const actionPending=useRef(false),readSequence=useRef(0),active=useRef(false);const request=useRef<{event:string;id:string}|null>(null);
 const scope={p_tenant:tenant,p_property:property};
 async function load(){const sequence=++readSequence.current;const [a,b]=await readConnections(tenant,property);if(sequence===readSequence.current){setRows(a);setReviews(b);setLoaded(true)}}
 useEffect(()=>{active.current=true;let live=true;const activeRef=active,sequenceRef=readSequence;const sequence=++sequenceRef.current;if(['owner','manager'].includes(role))readConnections(tenant,property).then(([a,b])=>{if(live&&sequence===sequenceRef.current){setRows(a);setReviews(b);setLoaded(true)}}).catch(e=>live&&sequence===sequenceRef.current&&setError(e.message));return()=>{live=false;activeRef.current=false;sequenceRef.current++}},[tenant,property,role]);
 async function run(fn:()=>Promise<void|string>,refresh=true){if(actionPending.current||!active.current)return;actionPending.current=true;setBusy(true);setError('');setNotice('');let timer:ReturnType<typeof setTimeout>|undefined;try{const {data}=await Promise.race([hotelClient().auth.getSession(),new Promise<never>((_,reject)=>{timer=setTimeout(()=>reject(Error('Account verification timed out. No connection action was sent. Sign in and retry.')),15000)})]);clearTimeout(timer);if(!active.current)return;if(!actor||data.session?.user?.id!==actor)throw Error('Your account changed. Reopen Connections before continuing.');const message=await fn();if(!active.current)return;setNotice(message||'Saved.');try{if(refresh)await load()}catch{if(active.current)setError('Saved, but refresh failed. Reopen Connections to refresh.')}}catch(e){if(active.current)setError(e instanceof Error?e.message:'Unable to update connection')}finally{clearTimeout(timer);actionPending.current=false;if(active.current)setBusy(false)}}
 if(!['owner','manager'].includes(role))return <section className="card pilot-empty">An owner or manager can review distribution connections.</section>;
 return <><section className="card pilot-settings"><h2>iRatePilot OTA delivery</h2><p>Map the OTA property and room types before accepting bookings. Your existing PMS can remain authoritative.</p>{error&&<div className="pilot-error" role="alert">{error}</div>}{notice&&<output className="pilot-notice">{notice}</output>}{rows.map(c=><div key={c.connection_id}><div className="pilot-list-row"><div><strong>{c.connection_id}</strong><small>{c.ota_property_id} · {c.inventory_authority==='existing-pms'?'Existing PMS remains authoritative':'iRatePilot owns inventory'}</small><span className={'pill '+(c.enabled?'green':'gray')}>{c.enabled?'Receiving enabled':'Disabled'}</span></div>{role==='owner'&&<div className="pilot-actions"><button className="text-button" disabled={busy} onClick={()=>setEdit(c)}>Edit</button><button className="secondary" disabled={busy} onClick={()=>void run(async()=>{await connectionCommand('enable_connection',{...scope,p_connection:c.connection_id,p_enabled:!c.enabled})})}>{c.enabled?'Disable':'Enable receiving'}</button></div>}</div><IratePilotPublishing actor={actor} tenant={tenant} property={property} role={role} connection={c} types={types} businessDate={businessDate} busy={busy} onBusy={setBusy}/></div>)}{!loaded&&<output>{error?'Connection information could not be loaded. Select Refresh to retry.':'Loading connections…'}</output>}{loaded&&!rows.length&&<p className="pilot-empty">No OTA connections configured.</p>}
 {role==='owner'&&<details className="pilot-connection-form" open={edit?true:undefined}><summary>{edit?'Edit '+edit.connection_id:'Configure an OTA connection'}</summary><form key={edit?.connection_id??'new'} onSubmit={e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),mapping:Record<string,string>={};for(const t of types){const ota=formText(f,'map-'+t.id).trim();if(ota){if(mapping[ota]){setError('Each OTA room ID must appear once.');return}mapping[ota]=t.id}}void run(async()=>{await connectionCommand('save_connection',{...scope,p_connection:edit?.connection_id??formText(f,'connection'),p_ota_property:edit?.ota_property_id??formText(f,'ota'),p_authority:formText(f,'authority'),p_room_types:mapping,p_secret:formText(f,'secret')||null});form.reset();setEdit(null);return 'Configuration saved disabled. Verify mapping and inventory, then enable receiving.'})}}><fieldset disabled={busy||!loaded} aria-label="Connection settings" style={{border:0,padding:0,margin:0,minWidth:0}}><label className="field">Connection identifier<input name="connection" pattern="[A-Za-z0-9_-]{1,80}" required defaultValue={edit?.connection_id} readOnly={!!edit}/></label><label className="field">OTA property ID<input name="ota" required maxLength={128} defaultValue={edit?.ota_property_id} readOnly={!!edit}/></label><label className="field">Inventory authority<select name="authority" defaultValue={edit?.inventory_authority??'existing-pms'}><option value="existing-pms">Keep existing PMS — review only</option><option value="iratepilot-pms">iRatePilot PMS — apply bookings to inventory</option></select></label><h3>Room-type mapping</h3>{types.map(t=><label className="field" key={t.id}>OTA room ID for {t.name}<input name={'map-'+t.id} maxLength={128} defaultValue={edit?Object.entries(edit.room_types).find(([,id])=>id===t.id)?.[0]:''}/></label>)}<label className="field">{edit?'Replacement signing secret (leave blank to keep current)':'Shared signing secret'}<input name="secret" type="password" autoComplete="new-password" minLength={32} maxLength={512} required={!edit}/></label><p>Use the same secret in the approved OTA sender. Saving disables receiving until you enable it again. No secret is displayed after saving.</p><button className="primary" disabled={busy||!types.length}>Save disabled connection</button>{edit&&<button type="button" className="secondary" onClick={()=>setEdit(null)}>Cancel editing</button>}</fieldset></form></details>}
 </section><PaymentReadiness actor={actor} tenant={tenant} property={property} role={role}/><section className="card"><div className="section-top"><h2>Reservation delivery review</h2><button className="secondary" disabled={busy} onClick={()=>void run(async()=>{await load();return 'Connections refreshed.'},false)}>Refresh</button></div><div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th>Booking</th><th>Version</th><th>Result</th><th>Review</th><th>Action</th></tr></thead><tbody>{reviews.map(r=>{const outcome=r.resolution_outcome??r.application_outcome;return <tr key={r.event_id}><td>{r.booking_id}</td><td>{r.source_version}{!r.is_current&&<small>Historical</small>}</td><td>{outcome.replaceAll('review:','')}</td><td>{r.review_reason??'—'}</td><td>{r.can_reprocess&&<button className="secondary" disabled={busy} onClick={()=>void run(async()=>{if(request.current?.event!==r.event_id)request.current={event:r.event_id,id:crypto.randomUUID()};const result=await connectionCommand<{applicationOutcome?:string;outcome?:string}>('reprocess',{...scope,p_event:r.event_id,p_request:request.current.id,p_reference:'Capacity reviewed by hotel manager in PMS'});request.current=null;return 'Capacity check result: '+(result.applicationOutcome??result.outcome??'recorded').replaceAll('review:','')})}>Recheck capacity</button>}</td></tr>})}</tbody></table>{loaded&&!reviews.length&&<p className="pilot-empty">No inbound delivery records yet.</p>}</div></section><p className="muted">Rechecking repeats capacity validation; it cannot force a booking into sold-out inventory. Other review results require a corrected OTA event or reconciliation.</p></>
}

type DeliveryControl={connection_id:string;provider:string;certified:boolean;outbound_enabled:boolean;pending:number;retrying:number;dead_letter:number;refresh_pending:number;refresh_blocked:number;last_delivered_at:string|null;certification_gates_passed:number;certification_gates_required:number};
function IratePilotPublishing({actor,tenant,property,role,connection,types,businessDate,busy,onBusy}:{actor:string;tenant:string;property:string;role:string;connection:Connection;types:RoomType[];businessDate:string;busy:boolean;onBusy:(value:boolean)=>void}){
 const [controls,setControls]=useState<DeliveryControl[]>([]),[plans,setPlans]=useState<RateBook['plans']>([]),[roomType,setRoomType]=useState(types[0]?.id??''),[ratePlan,setRatePlan]=useState(''),[start,setStart]=useState(businessDate),[end,setEnd]=useState(afterDays(businessDate,14)),[error,setError]=useState(''),[notice,setNotice]=useState('');const request=useRef<{key:string;id:string}|null>(null),running=useRef(false);const scope=useMemo(()=>({p_tenant:tenant,p_property:property}),[tenant,property]);
 const control=controls.find(x=>x.connection_id===connection.connection_id&&x.provider==='iratepilot');
 async function refresh(){const [health,rates]=await Promise.all([hotelRpc<DeliveryControl[]>('ota_ari_delivery_health',scope),hotelRpc<RateBook>('rates',{...scope,p_start:start,p_end:end})]);setControls(health);setPlans(rates.plans);}
 useEffect(()=>{let live=true;const args={p_tenant:tenant,p_property:property};Promise.all([hotelRpc<DeliveryControl[]>('ota_ari_delivery_health',args),hotelRpc<RateBook>('rates',{...args,p_start:start,p_end:end})]).then(([h,r])=>{if(live){setControls(h);setPlans(r.plans)}}).catch(e=>live&&setError(e instanceof Error?e.message:'Unable to load publishing status.'));return()=>{live=false}},[tenant,property,start,end]);
 async function act(fn:()=>Promise<string>){if(running.current)return;running.current=true;onBusy(true);setError('');setNotice('');try{const {data}=await hotelClient().auth.getSession();if(data.session?.user?.id!==actor)throw Error('Your account changed. Reopen Connections before continuing.');setNotice(await fn());try{await refresh()}catch{setError('The change may have saved, but its status could not be refreshed. Use Refresh before retrying.')}}catch(e){setError(e instanceof Error?e.message:'Unable to publish.')}finally{running.current=false;onBusy(false)}}
 const eligible=connection.inventory_authority==='iratepilot-pms'&&connection.enabled;
 const health=integrationHealth(connection,control);
 return <details className="pilot-connection-form"><summary>Availability and rates to iRatePilot.com</summary><div className="pilot-connection-form"><section className="pilot-connection-health" aria-label="Integration status"><div className="section-top"><h3>Connection status</h3><button className="text-button" type="button" onClick={()=>void refresh().catch(e=>setError(e instanceof Error?e.message:'Unable to refresh connection status.'))}>Refresh status</button></div><p><strong>{health.inbound.label}</strong> — {health.inbound.detail}</p><p role={health.outbound.state==='attention'?'alert':undefined}><strong>{health.outbound.label}</strong> — {health.outbound.detail}</p><small>Queue: {health.queue.waiting} waiting · {health.queue.retrying} retrying · {health.queue.needs_review} needs review. This is the last saved property queue snapshot; it does not check whether the OTA is currently reachable.</small></section><p><span className={'pill '+(control?.outbound_enabled?'green':'gray')}>{control?.outbound_enabled?'Outbound enabled':'Outbound disabled'}</span> <span className="muted">iRatePilot.com only · USD</span></p>{error&&<div className="pilot-error" role="alert">{error}</div>}{notice&&<output className="pilot-notice">{notice}</output>}<p>Saved inventory, reservations, nightly rates, rate-plan changes and room maintenance generate automatic sync updates. An owner can also publish a reviewed snapshot. No guest or payment details are sent.</p>{role==='owner'&&<button className="secondary" disabled={busy} onClick={()=>void act(async()=>{const enabled=!control?.outbound_enabled;await hotelRpc('ota_ari_save_control',{...scope,p_connection:connection.connection_id,p_provider:'iratepilot',p_certified:true,p_enabled:enabled});return enabled?'iRatePilot.com outbound enabled. Publish a snapshot to queue current rates and availability.':'iRatePilot.com outbound disabled.'})}>{control?.outbound_enabled?'Disable outbound':'Enable iRatePilot.com outbound'}</button>}{control&&<small>Delivery: {control.pending} pending · {control.retrying} retrying · {control.dead_letter} needs review. PMS changes: {control.refresh_pending} waiting · {control.refresh_blocked} blocked for configuration{control.last_delivered_at?' · Last delivered '+new Date(control.last_delivered_at).toLocaleString():''}</small>}{eligible&&control?.outbound_enabled&&<form onSubmit={e=>{e.preventDefault();if(!roomType||!ratePlan)return;const key=[connection.connection_id,roomType,ratePlan,start,end].join('|');if(request.current?.key!==key)request.current={key,id:crypto.randomUUID()};const requestId=request.current.id;void act(async()=>{const result=await hotelRpc<{event_id:string;replayed?:boolean}>('ota_ari_snapshot',{...scope,p_connection:connection.connection_id,p_request:requestId,p_room_type:roomType,p_rate_plan:ratePlan,p_start:start,p_end:end});request.current=null;return `Snapshot queued as ${result.event_id}${result.replayed?' (same request replayed)':''}. Delivery may still be pending.`})}}><label className="field">Room type<select value={roomType} onChange={e=>{setRoomType(e.target.value);setRatePlan('')}} disabled={busy}>{types.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label><label className="field">Active rate plan<select value={ratePlan} onChange={e=>setRatePlan(e.target.value)} disabled={busy}><option value="">Select a rate plan</option>{plans.filter(p=>p.active&&p.room_type_id===roomType).map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><div className="form-grid"><label className="field">First night<input type="date" value={start} onChange={e=>setStart(e.target.value)} disabled={busy} min={businessDate}/></label><label className="field">End date (exclusive)<input type="date" value={end} onChange={e=>setEnd(e.target.value)} disabled={busy} min={afterDays(start,1)} max={afterDays(start,366)}/></label></div><button className="primary" disabled={busy||!ratePlan||!connection.room_types||!Object.values(connection.room_types).includes(roomType)}>Queue availability and rates</button><p className="muted">Requires this connection to be enabled for inbound delivery too, a mapped room type, configured inventory and a saved rate for every night. The iRatePilot.com endpoint currently accepts USD only.</p></form>}{!eligible&&<p className="pilot-empty">Set this connection to iRatePilot-owned inventory and enable receiving before publishing availability.</p>}</div></details>
}
